@namespace sv_0e438cb9d80b45d3951ba5273edf5cbd.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="FullName" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Email" />
        @if (isValidatingEmail)
        {
            <span class="validating">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Phone" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Address"></textarea>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-next" @onclick="HandleNext" disabled="@isValidatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool isValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        { ErrorMessage = "Full name is required."; return; }
        if (string.IsNullOrWhiteSpace(Email))
        { ErrorMessage = "Email is required."; return; }
        if (string.IsNullOrWhiteSpace(Phone))
        { ErrorMessage = "Phone is required."; return; }
        if (string.IsNullOrWhiteSpace(Address))
        { ErrorMessage = "Address is required."; return; }

        if (ValidateEmail is not null)
        {
            isValidatingEmail = true;
            StateHasChanged();
            var valid = await ValidateEmail(Email);
            isValidatingEmail = false;
            if (!valid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_0e438cb9d80b45d3951ba5273edf5cbd.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryEditor Index="index"
                         Company="@entry.Company"
                         Title="@entry.Title"
                         StartDate="@entry.StartDate"
                         EndDate="@entry.EndDate"
                         IsCurrent="@entry.IsCurrent"
                         Description="@entry.Description"
                         ShowRemove="@(Entries.Count > 1)"
                         OnRemove="() => RemoveEntry(index)"
                         OnChanged="data => UpdateEntry(index, data)" />
    }

    <button type="button" class="btn-add" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn-back" @onclick="OnBack">Back</button>
        <button type="button" class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
            Entries.Add(new WorkEntryModel());
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryEditor.WorkEntryData data)
    {
        Entries[index] = new WorkEntryModel
        {
            Company = data.Company,
            Title = data.Title,
            StartDate = data.StartDate,
            EndDate = data.EndDate,
            IsCurrent = data.IsCurrent,
            Description = data.Description
        };
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

