@namespace sv_0e438cb9d80b45d3951ba5273edf5cbd.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var r = References[index];
        <ReferenceEditor Index="index"
                         Name="@r.Name"
                         Relationship="@r.Relationship"
                         Email="@r.Email"
                         Phone="@r.Phone"
                         ShowRemove="@(References.Count > 2)"
                         OnRemove="() => RemoveReference(index)"
                         OnChanged="data => UpdateReference(index, data)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn-back" @onclick="OnBack">Back</button>
        <button type="button" class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References.Add(new ReferenceModel());
            References.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceEditor.ReferenceData data)
    {
        References[index] = new ReferenceModel
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

