toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 0.85;
    cursor: pointer;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    margin-bottom: 0.25rem;
}

.step.active .step-number {
    background: #1976d2;
    color: white;
}

.step.completed .step-number {
    background: #4caf50;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e0e0e0;
    margin: 0 0.25rem;
    align-self: flex-start;
    margin-top: 1rem;
}

.step-connector.completed {
    background: #4caf50;
}

.checkmark {
    font-size: 1rem;
}

/* Form Elements */
.step-content {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-next,
.btn-submit {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #1565c0;
}

.btn-back {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-back:hover {
    background: #e0e0e0;
}

.btn-add {
    background: none;
    border: 1px dashed #1976d2;
    color: #1976d2;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background: #e3f2fd;
}

.btn-remove {
    background: none;
    border: none;
    color: #d32f2f;
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0.25rem 0.5rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-edit {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.btn-submit:disabled,
.btn-next:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Work Entry / Reference Editor */
.work-entry-editor,
.reference-editor {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: white;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.entry-header h4,
.reference-editor h4 {
    margin: 0 0 0.75rem 0;
    color: #555;
}

/* Messages */
.error-message {
    background: #ffebee;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.validating {
    font-size: 0.8rem;
    color: #666;
    font-style: italic;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #e0e0e0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.section-header h3 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin-bottom: 0.75rem;
}

.dates {
    font-size: 0.85rem;
    color: #666;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: white;
    padding: 0.75rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #4caf50;
    font-size: 1.5rem;
}

