@namespace sv_0e438cb9d80b45d3951ba5273edf5cbd.Components.Apply

<div class="work-entry-editor">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="HandleCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="HandleTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(StartDate)" @onchange="HandleStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatDate(EndDate)" disabled="@IsCurrent" @onchange="HandleEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="HandleDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private static string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";
    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");

    private void HandleCompanyChanged(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void HandleTitleChanged(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void HandleStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var d)) StartDate = d;
        NotifyChanged();
    }

    private void HandleEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : EndDate;
        NotifyChanged();
    }

    private void HandleCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void HandleDescriptionChanged(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

